// Generated by `just generate` from `src/plugins/claudetto-browser/slices/search/domain/search.ts`. Edit the source and run `just generate`.
// The pure parts of the web search of claudetto-browser.
// With the `backend` option `cloakbrowser`, the hooks module answers a `WebSearch` call with a search in CloakBrowser.
// It runs `agent-browser` with `$.process.run`, so the model keeps the tool that it knows.
// The `$` calls are in the adapter of the slice, because `$` is not followed across an import.

import {
  MAX_DOMAINS,
  MAX_OUTPUT_CHARS,
  RESULTS_SELECTOR,
  SEARCH_URL,
  SESSION_COUNTER_CHARS,
  SESSION_PREFIX,
  SESSION_RANDOM_CHARS,
} from "../limits.ts";
import {
  DOMAIN_DROPPED,
  EMPTY_PAGE,
  EXTENDED_MODE,
  MISSING_BINARY,
  PAGE_CUT,
  PAGE_HEADER,
} from "../prompts.ts";

/** The `WebSearch` input. The hooks module passes the input of the tool call. */
export interface SearchInput {
  query?: unknown;
  allowed_domains?: unknown;
  blocked_domains?: unknown;
  mode?: unknown;
}

/** One entry of a directory listing. */
export interface DirEntry {
  kind?: unknown;
  name?: unknown;
}

/** The result of one browser run, a `$.process.run` result. */
export interface BrowserRun {
  exitCode: number | null;
  stdout?: string;
  stderr?: string;
}

/** The names of one domain list that the query takes, and the entries that it drops. */
const splitDomains = (domains: unknown) => {
  const list: unknown[] = Array.isArray(domains) ? domains : [];
  const valid = list.filter(
    (d): d is string => typeof d === "string" && /^[\w.-]+$/.test(d),
  );
  const kept = valid.slice(0, MAX_DOMAINS);
  return {
    kept,
    dropped: list.filter((d) => !kept.includes(d as string)).map(String),
  };
};

/** The `-site:` terms of the blocked domains. A result must pass each one, so the terms stand apart. */
const blockedTerms = (domains: unknown): string[] =>
  splitDomains(domains).kept.map((d) => `-site:${d}`);

/**
 * The term of the allowed domains: a result may come from any one of them, so two or more are one group with `OR`.
 * Plain `site:a site:b` terms would read as `AND`, and a result cannot match both.
 */
const allowedTerms = (domains: unknown): string[] => {
  const terms = splitDomains(domains).kept.map((d) => `site:${d}`);
  return terms.length > 1 ? [`(${terms.join(" OR ")})`] : terms;
};

/** The notices for a filter or a mode that the search could not apply. They go in the result. */
export const searchNotices = (input: SearchInput | undefined): string[] => {
  const notices: string[] = [];
  for (const key of ["allowed_domains", "blocked_domains"] as const) {
    const { dropped } = splitDomains(input?.[key]);
    if (dropped.length > 0)
      notices.push(
        ...DOMAIN_DROPPED({ key, dropped: dropped.join(", ") }).split("\n"),
      );
  }
  if (input?.mode === "extended") notices.push(EXTENDED_MODE);
  return notices;
};

/** The query with the domain filters of the `WebSearch` input as search terms. */
export const searchQuery = (input: SearchInput | undefined): string | null => {
  const query = typeof input?.query === "string" ? input.query.trim() : "";
  if (!input || !query) return null;
  return [
    query,
    ...allowedTerms(input.allowed_domains),
    ...blockedTerms(input.blocked_domains),
  ].join(" ");
};

/** The URL of the search page for a query. */
export const searchUrl = (query: string): string =>
  `${SEARCH_URL}?q=${encodeURIComponent(query)}`;

let counter = 0;

/** A session name for one search: a counter and a random part, so that parallel searches differ. */
export const sessionName = (): string =>
  [
    SESSION_PREFIX,
    (++counter % 36 ** SESSION_COUNTER_CHARS).toString(36),
    Math.random()
      .toString(36)
      .slice(2, 2 + SESSION_RANDOM_CHARS),
  ].join("");

/** The folder of the CloakBrowser builds, under the home folder. */
export const CLOAK_DIR = ".cloakbrowser";

/** The path of the CloakBrowser binary inside a `chromium-<version>` folder. Only the macOS layout is known. */
export const CLOAK_BINARY = "Chromium.app/Contents/MacOS/Chromium";

const versionParts = (name: string): number[] =>
  name
    .slice("chromium-".length)
    .split(/[^\d]+/)
    .filter(Boolean)
    .map(Number);

/** Compares two `chromium-<version>` names by the numbers of the version. Gives a negative number when `a` is older. */
const compareBuilds = (a: string, b: string): number => {
  const x = versionParts(a);
  const y = versionParts(b);
  for (let i = 0; i < Math.max(x.length, y.length); i++) {
    const d = (x[i] ?? 0) - (y[i] ?? 0);
    if (d !== 0) return d;
  }
  return a < b ? -1 : a > b ? 1 : 0;
};

/**
 * The `chromium-*` folder names of a listing, newest first.
 * `$.fs.list` gives a symbolic link as `other` with `isLink`, so a linked build counts too.
 * The caller checks that the binary exists, which follows the link.
 */
export const cloakBuilds = (entries: unknown): string[] =>
  (Array.isArray(entries) ? entries : [])
    .filter(
      (e) =>
        (e?.kind === "dir" || e?.isLink === true) &&
        /^chromium-\d/.test(e.name),
    )
    .map((e) => e.name)
    .sort((a, b) => compareBuilds(b, a));

/** The path of the CloakBrowser binary in one build folder. */
export const cloakBinaryPath = (home: string, build: string): string =>
  `${home}/${CLOAK_DIR}/${build}/${CLOAK_BINARY}`;

/**
 * The argument vectors of the browser steps in one session: open the page, read the text of the results element, close.
 * Each step runs `agent-browser` with the CloakBrowser binary, because each search engine gives a bot check to the plain headless browser.
 */
export const steps = (url: string, session: string, binary: string) => {
  const base = [
    "agent-browser",
    "--session",
    session,
    "--executable-path",
    binary,
  ];
  return {
    open: [...base, "open", url],
    results: [
      ...base,
      "--max-output",
      String(MAX_OUTPUT_CHARS),
      "get",
      "text",
      RESULTS_SELECTOR,
    ],
    close: [...base, "close"],
  };
};

/** The reason that a run did not give a page, or `null` when the run gave one. */
export const failure = (run: BrowserRun, label: string): string | null => {
  if (run.exitCode === 0) return null;
  const detail = (run.stderr || run.stdout || "").trim().split("\n")[0];
  return `${label} failed with exit code ${run.exitCode}${detail ? `: ${detail}` : "."}`;
};

/**
 * The text of one `WebSearch` result, or `{ reason }` when the results element has no text.
 * The adapter reads only the results element, so a bot check page, which has no such element, never gets here.
 */
export const pageResult = (
  query: string,
  text: unknown,
  notices: readonly string[] = [],
): { reason: string } | { text: string } => {
  const raw = String(text ?? "");
  const page = raw.trim();
  if (!page) return { reason: EMPTY_PAGE };
  return {
    text: [
      PAGE_HEADER({ query }),
      ...notices,
      "",
      page,
      ...(raw.length >= MAX_OUTPUT_CHARS ? ["", PAGE_CUT] : []),
    ].join("\n"),
  };
};

/** The `WebSearch` result record for a text. */
export const searchResult = (
  query: string,
  text: string,
  startedAt: number,
  now = Date.now(),
) => ({
  query,
  results: [text],
  durationSeconds: Math.max(0, (now - startedAt) / 1000),
});

/** The deny text when the `backend` option is `cloakbrowser` and the binary is missing. */
export const missingBinary = (): string =>
  MISSING_BINARY({ cloakDir: CLOAK_DIR, cloakBinary: CLOAK_BINARY });

